import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus type.","frontmatter":{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus type."},"headers":[],"relativePath":"go-myanmar-payments/references/payment-callback.md","filePath":"go-myanmar-payments/references/payment-callback.md"}'),c={name:"go-myanmar-payments/references/payment-callback.md"};function r(s,t,n,l,u,i){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="paymentcallback-status" tabindex="-1">PaymentCallback &amp; Status <a class="header-anchor" href="#paymentcallback-status" aria-label="Permalink to &quot;PaymentCallback &amp; Status&quot;">​</a></h1><h2 id="paymentcallback" tabindex="-1">PaymentCallback <a class="header-anchor" href="#paymentcallback" aria-label="Permalink to &quot;PaymentCallback&quot;">​</a></h2><p>Returned by every gateway&#39;s <code>HandleCallback()</code> (and AYA&#39;s <code>VerifyRedirect()</code>) once the signature is verified.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>Status</code></td><td><code>PaymentStatus</code></td><td>The status mapped onto this package&#39;s statuses</td></tr><tr><td><code>GatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value, unmapped</td></tr><tr><td><code>GatewayReference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>Amount</code></td><td><code>string</code></td><td>The amount the gateway reports, exactly as it sent it</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The verified payload, as decoded JSON (<code>json.Number</code>, never <code>float64</code>)</td></tr><tr><td><code>Acknowledgement</code></td><td><code>Acknowledgement</code></td><td>The response the gateway expects</td></tr><tr><td><code>IsSuccessful()</code></td><td><code>bool</code></td><td><code>Status == StatusSuccessful</code></td></tr></tbody></table><p>Build one yourself to test your own fulfillment code, as a struct literal: <code>&amp;myanmarpayments.PaymentCallback{OrderID: …, Status: …, GatewayStatus: …}</code>. Fields you leave out are zero values, so set <code>Acknowledgement</code> to <code>myanmarpayments.DefaultAcknowledgement()</code> when your code writes it.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to &quot;Acknowledgement&quot;">​</a></h2><p>A struct.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Status</code></td><td><code>int</code></td><td>HTTP status; <code>0</code> is written as <code>200</code></td></tr><tr><td><code>Body</code></td><td><code>string</code></td><td>Response body, e.g. KBZ Pay&#39;s <code>success</code>; empty by default</td></tr><tr><td><code>Headers</code></td><td><code>map[string]string</code></td><td>Response headers, <code>{&quot;Content-Type&quot;: &quot;text/plain&quot;}</code> by default</td></tr><tr><td><code>Write(w)</code></td><td><code>error</code></td><td>Writes the headers, status and body to an <code>http.ResponseWriter</code></td></tr></tbody></table><p><code>DefaultAcknowledgement()</code> is an empty <code>200</code> with <code>Content-Type: text/plain</code>. Write it with your framework&#39;s response writer, see <a href="/go-myanmar-payments/callbacks.html#acknowledging">Acknowledging</a>.</p><h2 id="paymentstatusresult" tabindex="-1">PaymentStatusResult <a class="header-anchor" href="#paymentstatusresult" aria-label="Permalink to &quot;PaymentStatusResult&quot;">​</a></h2><p>Returned by <code>kbz.Status()</code>, <code>aya.Status()</code> and <code>yoma.Status()</code>. A struct.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID; <code>&quot;&quot;</code> for Yoma, which returns only the reference</td></tr><tr><td><code>Status</code></td><td><code>PaymentStatus</code></td><td>The mapped status</td></tr><tr><td><code>GatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value</td></tr><tr><td><code>GatewayReference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>Amount</code></td><td><code>string</code></td><td>The amount the gateway reports</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response</td></tr><tr><td><code>IsSuccessful()</code></td><td><code>bool</code></td><td><code>Status == StatusSuccessful</code></td></tr></tbody></table><h2 id="callbackrequest" tabindex="-1">CallbackRequest <a class="header-anchor" href="#callbackrequest" aria-label="Permalink to &quot;CallbackRequest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>NewCallbackRequestFromHTTP(r)</code></td><td><code>(*CallbackRequest, error)</code></td><td>From an <code>*http.Request</code>: reads the body once and restores it</td></tr><tr><td><code>NewCallbackRequest(body, header, query)</code></td><td><code>*CallbackRequest</code></td><td>From the raw parts: the body as <code>[]byte</code>, the headers as an <code>http.Header</code>, the query string as <code>url.Values</code>; <code>nil</code> header and query are allowed</td></tr><tr><td><code>NewCallbackRequestFromJSON(payload, header)</code></td><td><code>(*CallbackRequest, error)</code></td><td>From a decoded payload, encoded as a JSON body with <code>Content-Type: application/json</code></td></tr><tr><td><code>Body</code></td><td><code>[]byte</code></td><td>The raw body, exactly as received</td></tr><tr><td><code>Header</code></td><td><code>http.Header</code></td><td>The request headers</td></tr><tr><td><code>Query</code></td><td><code>url.Values</code></td><td>The query string values</td></tr><tr><td><code>HeaderValue(name)</code></td><td><code>string</code></td><td>One header, case-insensitively, or <code>&quot;&quot;</code></td></tr><tr><td><code>ParsedBody()</code></td><td><code>map[string]any</code></td><td>The body decoded as JSON (when it is a JSON object) or a urlencoded form; JSON numbers become <code>json.Number</code></td></tr><tr><td><code>Input()</code></td><td><code>map[string]any</code></td><td>The body merged over the query string</td></tr><tr><td><code>QueryInput()</code></td><td><code>map[string]any</code></td><td>The query string merged over the body</td></tr></tbody></table><h2 id="paymentstatus" tabindex="-1">PaymentStatus <a class="header-anchor" href="#paymentstatus" aria-label="Permalink to &quot;PaymentStatus&quot;">​</a></h2><p><code>type PaymentStatus string</code>: constants are strings, so they compare equal to their values and <code>string(status)</code> is the value.</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody><tr><td><code>StatusSuccessful</code></td><td><code>successful</code></td></tr><tr><td><code>StatusPending</code></td><td><code>pending</code></td></tr><tr><td><code>StatusFailed</code></td><td><code>failed</code></td></tr><tr><td><code>StatusCanceled</code></td><td><code>canceled</code></td></tr><tr><td><code>StatusExpired</code></td><td><code>expired</code></td></tr><tr><td><code>StatusUnknown</code></td><td><code>unknown</code></td></tr></tbody></table><p><code>myanmarpayments.PaymentStatuses()</code> lists every status. <code>status.IsFinal()</code> is <code>false</code> for <code>StatusPending</code> and <code>StatusUnknown</code>. <code>ResolveStatus(statuses, gatewayStatus)</code> maps a trimmed gateway value through a <code>map[string]PaymentStatus</code> and returns <code>StatusUnknown</code> when it is not listed.</p>',18)])])}const m=e(c,[["render",r]]);export{h as __pageData,m as default};
